Here is the commit message:
Fixed mingw compile error introduced in 0a482f255:
 'm_state_enum' undeclared identifier, explicit cast isn't necessary so only
 include it when MSVC C++ fix is needed

Here is the root cause:
The bug was caused by the introduction of an undeclared identifier `m_state_enum` in the code, which occurred during a previous commit (0a482f255). This issue arises when compiling with Microsoft Visual C++, where the explicit cast to `m_state_enum` is necessary, but the identifier is not defined in the context of the code, leading to a compilation error. The patch resolves this by conditionally including the cast only for MSVC, allowing for a direct assignment in other compilers.

Here is the patch:

 static void
 M_Quit_Key(int key)
 {
 #if 0
     switch (key) {
     case K_ESCAPE:
     case 'n':
     case 'N':
 	if (wasInMenus) {
+#ifdef _MSC_VER
 	    m_state = (m_state_enum)m_quit_prevstate;
+#else
+	    m_state = m_quit_prevstate;
+#endif
 	    m_entersound = true;
 	} else {
 	    key_dest = key_game;
 	    m_state = m_none;
 	}
 	break;

     case 'Y':
     case 'y':
 	key_dest = key_console;
 	Host_Quit_f();
 	break;

     default:
 	break;
     }
 #else
 	key_dest = key_console;
 	Host_Quit_f();
    environ_cb(RETRO_ENVIRONMENT_SHUTDOWN, NULL);
 #endif
 }


 static void
 M_Quit_Draw(void)
 {
     if (wasInMenus) {
+#ifdef _MSC_VER
 	m_state = (m_state_enum)m_quit_prevstate;
+#else
+	m_state = m_quit_prevstate;
+#endif
 	m_recursiveDraw = true;
 	M_Draw();
 	m_state = m_quit;
     }

